# 外部 ESP 完整实现

四个文件，header-only，无第三方依赖，`cl` 直接编。核心是 `Pattern.h` 的 AOB 扫描器 + `Offsets.h` 的偏移解析（AOB 主路径，cs2-dumper 输出做交叉校验），`main.cpp` 里是读取、W2S 和 GDI overlay。

## 目录

```
cs2esp/
  Mem.h        进程/模块/RPM/镜像读取
  Pattern.h    AOB 扫描 + RIP 相对解引用
  Offsets.h    偏移解析 + 自检
  main.cpp     实体遍历 / W2S / overlay
```

## Mem.h

```cpp
#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <cstdint>
#include <vector>
#include <cwchar>

class Process {
public:
    Process() = default;
    Process(const Process&) = delete;
    Process& operator=(const Process&) = delete;
    ~Process() { if (h_) CloseHandle(h_); }

    bool Attach(const wchar_t* procName, const wchar_t* modName)
    {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe{}; pe.dwSize = sizeof(pe);
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
            if (_wcsicmp(pe.szExeFile, procName) == 0) { pid_ = pe.th32ProcessID; break; }
        CloseHandle(snap);
        if (!pid_) return false;

        HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
        if (ms != INVALID_HANDLE_VALUE) {
            MODULEENTRY32W me{}; me.dwSize = sizeof(me);
            for (BOOL ok = Module32FirstW(ms, &me); ok; ok = Module32NextW(ms, &me))
                if (_wcsicmp(me.szModule, modName) == 0) {
                    base_ = (uintptr_t)me.modBaseAddr;
                    size_ = (size_t)me.modBaseSize;
                    break;
                }
            CloseHandle(ms);
        }
        if (!base_ || !size_) return false;

        h_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid_);
        return h_ != nullptr;
    }

    HANDLE    handle() const { return h_; }
    DWORD     pid()    const { return pid_; }
    uintptr_t base()   const { return base_; }
    size_t    size()   const { return size_; }

    template <class T> bool Read(uintptr_t addr, T& out) const {
        return ReadProcessMemory(h_, (LPCVOID)addr, &out, sizeof(T), nullptr) != FALSE;
    }
    template <class T> T Read(uintptr_t addr) const {
        T v{}; ReadProcessMemory(h_, (LPCVOID)addr, &v, sizeof(T), nullptr); return v;
    }

    // 整模块快照：按 VirtualQueryEx 逐 region 拉，未提交页留 0，签名不会跨 region
    std::vector<uint8_t> ReadImage() const
    {
        std::vector<uint8_t> img(size_, 0);
        uintptr_t addr = base_, end = base_ + size_;
        while (addr < end) {
            MEMORY_BASIC_INFORMATION mbi{};
            if (!VirtualQueryEx(h_, (LPCVOID)addr, &mbi, sizeof(mbi))) break;
            uintptr_t rEnd = (uintptr_t)mbi.BaseAddress + mbi.RegionSize;
            if (rEnd <= addr) break;                      // 防 RegionSize==0 死循环
            if (mbi.State == MEM_COMMIT && !(mbi.Protect & (PAGE_NOACCESS | PAGE_GUARD))) {
                uintptr_t s = addr > (uintptr_t)mbi.BaseAddress ? addr : (uintptr_t)mbi.BaseAddress;
                uintptr_t e = rEnd < end ? rEnd : end;
                if (e > s)
                    ReadProcessMemory(h_, (LPCVOID)s, img.data() + (s - base_), e - s, nullptr);
            }
            addr = rEnd;
        }
        return img;
    }

private:
    HANDLE    h_    = nullptr;
    DWORD     pid_  = 0;
    uintptr_t base_ = 0;
    size_t    size_ = 0;
};
```

## Pattern.h

```cpp
#pragma once
#include <cstdint>
#include <cstring>
#include <cstddef>
#include <vector>
#include "Mem.h"

struct Pattern {
    std::vector<uint8_t> bytes;   // 通配位填 0
    std::vector<uint8_t> fixed;   // 1 = 必须比对

    static int Hexv(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    }

    static bool Parse(const char* sig, Pattern& out)
    {
        out.bytes.clear(); out.fixed.clear();
        const char* p = sig;
        while (*p) {
            while (*p == ' ') ++p;
            if (!*p) break;
            if (*p == '?') {
                while (*p == '?') ++p;
                out.bytes.push_back(0); out.fixed.push_back(0);
            } else {
                int hi = Hexv(p[0]);
                int lo = (p[1] && p[1] != ' ') ? Hexv(p[1]) : -1;
                if (hi < 0 || lo < 0) return false;
                out.bytes.push_back((uint8_t)(hi * 16 + lo));
                out.fixed.push_back(1);
                ++p;
            }
            while (*p && *p != ' ') ++p;
        }
        return !out.bytes.empty();
    }
};

// 首固定字节用 memchr 跳，比逐字节快一个量级
inline size_t ScanBuffer(const std::vector<uint8_t>& img, const Pattern& p, size_t from = 0)
{
    const size_t n = img.size(), m = p.bytes.size();
    if (m == 0 || m > n) return SIZE_MAX;

    size_t firstFixed = 0;
    while (firstFixed < m && !p.fixed[firstFixed]) ++firstFixed;
    if (firstFixed == m) return SIZE_MAX;

    size_t i = from;
    const size_t last = n - m + firstFixed;   // 首固定字节的最后一个合法位置
    while (i + m <= n) {
        size_t pos = i + firstFixed;
        if (pos > last) return SIZE_MAX;
        const uint8_t* hit = (const uint8_t*)std::memchr(img.data() + pos, p.bytes[firstFixed], last - pos + 1);
        if (!hit) return SIZE_MAX;
        size_t cand = (size_t)(hit - img.data()) - firstFixed;
        bool ok = true;
        for (size_t k = 0; k < m; ++k)
            if (p.fixed[k] && img[cand + k] != p.bytes[k]) { ok = false; break; }
        if (ok) return cand;
        i = cand + 1;
    }
    return SIZE_MAX;
}

// 扫描整模块，返回模块内偏移（0 表示未命中，.text 不会落在 0）
inline uintptr_t ScanModule(const Process& proc, const char* sig, size_t from = 0)
{
    Pattern p;
    if (!Pattern::Parse(sig, p)) return 0;
    std::vector<uint8_t> img = proc.ReadImage();
    size_t off = ScanBuffer(img, p, from);
    return off == SIZE_MAX ? 0 : (uintptr_t)off;
}

// 48 8B 0D <rel32> -> 目标全局：hit 处 opOffset=3, instrLen=7
inline uintptr_t ResolveRip(const Process& proc, uintptr_t hit, int opOffset, int instrLen)
{
    int32_t rel = 0;
    if (!proc.Read<int32_t>(hit + opOffset, rel)) return 0;
    return hit + instrLen + (intptr_t)rel;
}
