```cpp
#pragma once
#include <cstdio>
#include <cstdint>
#include <cctype>
#include <string>
#include <unordered_map>
#include "Mem.h"
#include "Pattern.h"

struct SigDef { const char* name; const char* sig; int opOffset; int instrLen; };

// CANDIDATE：三条签名随 build 漂移，必须用下面 Validate() 的断言确认后再用
static const SigDef kSigs[] = {
    { "dwEntityList",      "48 8B 0D ? ? ? ? 48 89 7C 24 ? 8B FA",      3, 7 },
    { "dwLocalPlayerPawn", "48 8D 05 ? ? ? ? 48 89 05 ? ? ? ? 48 89 C7", 3, 7 },
    { "dwViewMatrix",      "48 8D 0D ? ? ? ? 48 C1 E0 06",              3, 7 },
};

struct Offsets {
    uintptr_t entityList      = 0;
    uintptr_t localPlayerPawn = 0;
    uintptr_t viewMatrix      = 0;

    uintptr_t health          = 0;   // m_iHealth
    uintptr_t teamNum         = 0;   // m_iTeamNum
    uintptr_t lifeState       = 0;   // m_lifeState
    uintptr_t gameSceneNode   = 0;   // m_pGameSceneNode
    uintptr_t sceneNodeOrigin = 0;   // CGameSceneNode::m_vecAbsOrigin
    uintptr_t viewOffset      = 0;   // m_vecViewOffset
};

// 解析 cs2-dumper 的 offsets.hpp / client_dll.hpp（constexpr ... = 0xNN;）以及 JSON 的 "k": "0xNN"
inline void LoadDumpFile(const char* path, std::unordered_map<std::string, uintptr_t>& out)
{
    FILE* f = fopen(path, "rb");
    if (!f) return;
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    if (n <= 0) { fclose(f); return; }
    std::string s((size_t)n, '\0');
    fread(&s[0], 1, (size_t)n, f);
    fclose(f);

    size_t i = 0;
    while ((i = s.find("0x", i)) != std::string::npos) {
        size_t j = i;
        while (j > 0 && isspace((unsigned char)s[j - 1])) --j;
        size_t k = j;
        while (k > 0 && (isalnum((unsigned char)s[k - 1]) || s[k - 1] == '_')) --k;
        std::string name = s.substr(k, j - k);

        size_t p = i + 2; uintptr_t v = 0; bool any = false;
        while (p < s.size() && isxdigit((unsigned char)s[p])) {
            char c = s[p++];
            int d = (c <= '9') ? c - '0' : (c | 0x20) - 'a' + 10;
            v = (v << 4) | (uintptr_t)d; any = true;
        }
        if (any && !name.empty() && name.find("0x") == std::string::npos)
            out.emplace(name, v);
        i = p;
    }
}

inline void ResolveOffsets(const Process& proc, Offsets& o)
{
    std::unordered_map<std::string, uintptr_t> dump;
    LoadDumpFile("offsets.hpp", dump);
    LoadDumpFile("client_dll.hpp", dump);

    auto pick = [&](const char* n, uintptr_t& dst, const char* label) {
        auto it = dump.find(n);
        if (it != dump.end()) { dst = it->second; printf("  %-20s = 0x%llX  (dumper)\n", label, (unsigned long long)dst); }
    };

    // 1) 先试 dumper 输出
    pick("dwEntityList",      o.entityList,      "dwEntityList");
    pick("dwLocalPlayerPawn", o.localPlayerPawn, "dwLocalPlayerPawn");
    pick("dwViewMatrix",      o.viewMatrix,      "dwViewMatrix");
    pick("m_iHealth",         o.health,          "m_iHealth");
    pick("m_iTeamNum",        o.teamNum,         "m_iTeamNum");
    pick("m_lifeState",       o.lifeState,       "m_lifeState");
    pick("m_pGameSceneNode",  o.gameSceneNode,   "m_pGameSceneNode");
    pick("m_vecAbsOrigin",    o.sceneNodeOrigin, "m_vecAbsOrigin");
    pick("m_vecViewOffset",   o.viewOffset,      "m_vecViewOffset");

    // 2) 缺的走 AOB
    for (const auto& sd : kSigs) {
        uintptr_t* dst = nullptr;
        if (!strcmp(sd.name, "dwEntityList"))      dst = &o.entityList;
        if (!strcmp(sd.name, "dwLocalPlayerPawn")) dst = &o.localPlayerPawn;
        if (!strcmp(sd.name, "dwViewMatrix"))      dst = &o.viewMatrix;
        if (!dst || *dst) continue;

        uintptr_t hit = ScanModule(proc, sd.sig);
        if (!hit) { printf("  [!] %-20s 未命中\n", sd.name); continue; }
        *dst = ResolveRip(proc, proc.base() + hit, sd.opOffset, sd.instrLen) - proc.base();
        printf("  %-20s = 0x%llX  (AOB @ +0x%llX)\n", sd.name, (unsigned long long)*dst, (unsigned long long)hit);
    }
}

// 自检：把解析结果拿到真实内存上验证，不通过就别画
inline bool Validate(const Process& proc, const Offsets& o)
{
    bool ok = true;
    uintptr_t base = proc.base();

    uintptr_t list = proc.Read<uintptr_t>(base + o.entityList);
    if (!list) { printf("  [FAIL] entityList 解引用为 0\n"); ok = false; }
    else {
        uintptr_t chunk = proc.Read<uintptr_t>(list + 0x10);
        if (!chunk) { printf("  [FAIL] entityList+0x10 非指针\n"); ok = false; }
        else printf("  [ OK ] entityList=%p chunk0=%p\n", (void*)list, (void*)chunk);
    }

    uintptr_t pawn = proc.Read<uintptr_t>(base + o.localPlayerPawn);
    printf("  [%s] localPlayerPawn=%p\n", pawn ? " OK " : "FAIL", (void*)pawn);

    float vm[16]{};
    proc.Read(base + o.viewMatrix, vm[0]);                 // 占位，真读在下面
    proc.Read(base + o.viewMatrix, *(float(*)[16])vm);
    bool finite = true;
    for (int i = 0; i < 16; ++i)
        if (!(vm[i] > -1e6f && vm[i] < 1e6f)) finite = false;
    printf("  [%s] viewMatrix[15]=%.3f\n", finite ? " OK " : "FAIL", vm[15]);
    return ok && pawn && finite;
}
