```cpp
#include <windows.h>
#include <cstdio>
#include <cmath>
#include <vector>
#include <algorithm>
#include "Mem.h"
#include "Pattern.h"
#include "Offsets.h"

static Process g_proc;
static Offsets g_off;

struct Vec3 { float x, y, z; };
struct Mat4 { float m[16]; };

static bool W2S(const Mat4& vm, const Vec3& p, float w, float h, POINT& out)
{
    const float cw = vm.m[12]*p.x + vm.m[13]*p.y + vm.m[14]*p.z + vm.m[15];
    if (cw < 0.001f) return false;                       // 在相机后面
    const float cx = vm.m[0]*p.x + vm.m[1]*p.y + vm.m[2]*p.z + vm.m[3];
    const float cy = vm.m[4]*p.x + vm.m[5]*p.y + vm.m[6]*p.z + vm.m[7];
    const float inv = 1.0f / cw;
    out.x = (LONG)lroundf((w * 0.5f) * (1.0f + cx * inv));
    out.y = (LONG)lroundf((h * 0.5f) * (1.0f - cy * inv));
    return true;
}

// CGameEntitySystem: list + 8*(idx>>9) + 0x10 -> chunk; chunk + 8*(idx&0x1FF) -> entity
static uintptr_t GetEntity(uintptr_t list, int idx)
{
    if (idx < 0 || idx > 0x7FFF) return 0;
    uintptr_t chunk = g_proc.Read<uintptr_t>(list + 0x8 * (idx >> 9) + 0x10);
    if (!chunk) return 0;
    return g_proc.Read<uintptr_t>(chunk + 0x8 * (idx & 0x1FF));
}

static void DrawBox(HDC dc, int l, int t, int r, int b, COLORREF c)
{
    HPEN pen = CreatePen(PS_SOLID, 1, c);
    HGDIOBJ op = SelectObject(dc, pen);
    HGDIOBJ ob = SelectObject(dc, GetStockObject(NULL_BRUSH));
    MoveToEx(dc, l, t, nullptr); LineTo(dc, r, t);
    LineTo(dc, r, b); LineTo(dc, l, b); LineTo(dc, l, t);
    SelectObject(dc, ob); SelectObject(dc, op);
    DeleteObject(pen);
}

static void Render(HDC dc, int w, int h)
{
    const uintptr_t base = g_proc.base();

    Mat4 vm;
    if (!g_proc.Read(base + g_off.viewMatrix, *(float(*)[16])vm.m)) return;

    const uintptr_t list = g_proc.Read<uintptr_t>(base + g_off.entityList);
    if (!list) return;

    const uintptr_t local  = g_proc.Read<uintptr_t>(base + g_off.localPlayerPawn);
    const int       myTeam = local ? g_proc.Read<int>(local + g_off.teamNum) : 0;

    for (int i = 1; i <= 64; ++i) {
        const uintptr_t e = GetEntity(list, i);
        if (!e || e == local) continue;

        const int hp = g_proc.Read<int>(e + g_off.health);
        if (hp <= 0 || hp > 100) continue;

        if (g_proc.Read<int>(e + g_off.teamNum) == myTeam) continue;

        const uintptr_t node = g_proc.Read<uintptr_t>(e + g_off.gameSceneNode);
        if (!node) continue;

        Vec3 origin  = g_proc.Read<Vec3>(node + g_off.sceneNodeOrigin);
        Vec3 viewOff = g_proc.Read<Vec3>(e    + g_off.viewOffset);
        if (viewOff.z < 10.0f || viewOff.z > 90.0f) viewOff = { 0, 0, 64 };   // 兜底

        POINT feet{}, head{};
        if (!W2S(vm, origin, (float)w, (float)h, feet)) continue;
        if (!W2S(vm, { origin.x + viewOff.x, origin.y + viewOff.y, origin.z + viewOff.z },
                 (float)w, (float)h, head)) continue;

        const float bh = (float)(feet.y - head.y);
        if (bh < 6.0f || bh > (float)h) continue;
        const float bw = bh * 0.42f;
        const int l = (int)(feet.x - bw * 0.5f), r = (int)(feet.x + bw * 0.5f);

        DrawBox(dc, l, head.y, r, feet.y, RGB(0, 255, 64));

        // 血条
        const int bx = l - 5, bhgt = feet.y - head.y;
        const int fill = (int)(bhgt * (hp / 100.0f));
        HBRUSH br = CreateSolidBrush(RGB(255, 60, 60));
        RECT bar{ bx, feet.y - fill, bx + 2, feet.y };
        FillRect(dc, &bar, br);
        DeleteObject(br);
    }
}

static HWND FindGameWindow(DWORD pid)
{
    struct Ctx { DWORD pid; HWND hwnd; } ctx{ pid, nullptr };
    EnumWindows([](HWND h, LPARAM lp) -> BOOL {
        auto* c = (Ctx*)lp;
        DWORD p = 0; GetWindowThreadProcessId(h, &p);
        if (p == c->pid && IsWindowVisible(h) && GetWindow(h, GW_OWNER) == nullptr) {
            c->hwnd = h; return FALSE;
        }
        return TRUE;
    }, (LPARAM)&ctx);
    return ctx.hwnd;
}

static LRESULT CALLBACK WndProc(HWND h, UINT m, WPARAM w, LPARAM l)
{
    if (m == WM_NCHITTEST) return HTTRANSPARENT;
    if (m == WM_DESTROY)   { PostQuitMessage(0); return 0; }
    return DefWindowProcW(h, m, w, l);
}

int main()
{
    SetProcessDPIAware();

    if (!g_proc.Attach(L"cs2.exe", L"client.dll")) {
        printf("attach 失败（没跑 cs2.exe / 不是 64 位构建 / 权限不足）\n");
        return 1;
    }
    printf("pid=%lu base=0x%llX size=0x%zX\n",
           g_proc.pid(), (unsigned long long)g_proc.base(), g_proc.size());

    ResolveOffsets(g_proc, g_off);
    if (!Validate(g_proc, g_off)) {
        printf("偏移自检失败，按住不表；补齐 offsets.hpp 或修正 kSigs 后重跑\n");
    }

    const uintptr_t base = g_proc.base();
    const uintptr_t local = g_proc.Read<uintptr_t>(base + g_off.localPlayerPawn);
    if (local) {
        // 自投影校验：本地玩家眼睛应落在屏幕中心附近
        Mat4 vm; g_proc.Read(base + g_off.viewMatrix, *(float(*)[16])vm.m);
        uintptr_t node = g_proc.Read<uintptr_t>(local + g_off.gameSceneNode);
        Vec3 org = g_proc.Read<Vec3>(node + g_off.sceneNodeOrigin);
        Vec3 vo  = g_proc.Read<Vec3>(local + g_off.viewOffset);
        POINT p{};
        if (W2S(vm, { org.x + vo.x, org.y + vo.y, org.z + vo.z }, 1920.f, 1080.f, p))
            printf("自投影(假定1920x1080) -> (%ld,%ld)，应接近(960,540)\n", p.x, p.y);
    }

    WNDCLASSEXW wc{}; wc.cbSize = sizeof(wc);
    wc.lpfnWndProc = WndProc;
    wc.hInstance = GetModuleHandleW(nullptr);
    wc.lpszClassName = L"cs2ovl";
    RegisterClassExW(&wc);

    HWND hwnd = CreateWindowExW(
        WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOPMOST | WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE,
        L"cs2ovl", L"", WS_POPUP, 0, 0, 100, 100, nullptr, nullptr, wc.hInstance, nullptr);
    if (!hwnd) return 2;

    SetLayeredWindowAttributes(hwnd, RGB(0,0,0), 255, LWA_COLORKEY);
    ShowWindow(hwnd, SW_SHOWNOACTIVATE);
    SetWindowPos(hwnd, HWND_TOPMOST, 0,0,0,0, SWP_NOMOVE|SWP_NOSIZE|SWP_NOACTIVATE);

    HDC     memDC = nullptr;
    HBITMAP bmp   = nullptr;
    int     bw = 0, bhh = 0;
    HWND    game = nullptr;

    for (;;) {
        MSG msg;
        while (PeekMessageW(&msg, nullptr, 0, 0, PM_REMOVE)) {
            if (msg.message == WM_QUIT) return 0;
            TranslateMessage(&msg); DispatchMessageW(&msg);
        }

        if (!game || !IsWindow(game)) game = FindGameWindow(g_proc.pid());
        if (game) {
            RECT rc{}; GetClientRect(game, &rc);
            POINT tl{ 0, 0 }; ClientToScreen(game, &tl);
            const int w = rc.right - rc.left, h = rc.bottom - rc.top;
            if (w > 0 && h > 0) {
                SetWindowPos(hwnd, HWND_TOPMOST, tl.x, tl.y, w, h, SWP_NOACTIVATE);
                if (w != bw || h != bhh) {
                    if (bmp)   DeleteObject(bmp);
                    if (memDC) DeleteDC(memDC);
                    HDC sdc = GetDC(hwnd);
                    memDC = CreateCompatibleDC(sdc);
                    bmp   = CreateCompatibleBitmap(sdc, w, h);
                    SelectObject(memDC, bmp);
                    ReleaseDC(hwnd, sdc);
                    bw = w; bhh = h;
                }
                RECT full{ 0, 0, w, h };
                FillRect(memDC, &full, (HBRUSH)GetStockObject(BLACK_BRUSH));
                Render(memDC, w, h);
                HDC sdc = GetDC(hwnd);
                BitBlt(sdc, 0, 0, w, h, memDC, 0, 0, SRCCOPY);
                ReleaseDC(hwnd, sdc);
            }
        }
        Sleep(1);
    }
}
