WSAECONNREFUSED = 10061
WSAETIMEDOUT = 10060

# ---------------------------------------------------------------- 校验和 / 发包


def checksum(data):
    """RFC1071 16-bit one's complement checksum。"""
    if len(data) & 1:
        data += b'\x00'
    total = sum(struct.unpack('!%dH' % (len(data) // 2), data))
    total = (total >> 16) + (total & 0xFFFF)
    total += total >> 16
    return ~total & 0xFFFF


def build_tcp_packet(src_ip, dst_ip, sport, dport, seq, ack, flags, window=64240):
    """构造完整 IPv4 + TCP 报文（IP_HDRINCL 用）。flags: SYN=0x02 RST=0x04 ACK=0x10"""
    tcp = struct.pack('!HHIIBBHHH',
                      sport, dport, seq, ack,
                      (5 << 4), flags, window, 0, 0)
    pseudo = (socket.inet_aton(src_ip) + socket.inet_aton(dst_ip) +
              struct.pack('!BBH', 0, socket.IPPROTO_TCP, len(tcp)))
    csum = checksum(pseudo + tcp)
    tcp = struct.pack('!HHIIBBHHH',
                      sport, dport, seq, ack,
                      (5 << 4), flags, window, csum, 0)

    ip = struct.pack('!BBHHHBBH4s4s',
                     0x45, 0, 20 + len(tcp), random.randint(1, 0xFFFF),
                     0x4000, 64, socket.IPPROTO_TCP, 0,
                     socket.inet_aton(src_ip), socket.inet_aton(dst_ip))
    ip = ip[:10] + struct.pack('!H', checksum(ip)) + ip[12:]
    return ip + tcp


def local_ip_for(dst_ip):
    """把路由决策交给内核: 连一个 UDP 端口然后读本地地址。"""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect((dst_ip, 9))
        return s.getsockname()[0]
    except OSError:
        return '0.0.0.0'
    finally:
        s.close()

# ---------------------------------------------------------------- SYN 扫描器


class SynScanner:
    """原生 raw socket 实现。Linux / 装了 Npcap 的 Windows 可用。"""

    def __init__(self, target, timeout=1.0, retries=1, src_ip=None, verbose=False):
        self.target = target
        self.timeout = timeout
        self.retries = retries
        self.verbose = verbose
        self.src_ip = src_ip or local_ip_for(target)

        self._pending = {}                       # (dport, sport) -> record
        self._lock = threading.Lock()
        self._send_lock = threading.Lock()
        self._stop = threading.Event()

        self._recv_sock = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_TCP)
        try:
            self._recv_sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4 << 20)
        except OSError:
            pass
        self._recv_sock.settimeout(0.2)

        self._send_sock = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_TCP)
        self._send_sock.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)

        self._sniffer = threading.Thread(target=self._sniff_loop, daemon=True)
        self._sniffer.start()

    def _sniff_loop(self):
        while not self._stop.is_set():
            try:
                pkt, _ = self._recv_sock.recvfrom(65535)
            except socket.timeout:
                continue
            except OSError:
                break
            if len(pkt) < 40:
                continue
            ihl = (pkt[0] & 0x0F) * 4
            if ihl < 20 or len(pkt) < ihl + 20:
                continue
            if socket.inet_ntoa(pkt[12:16]) != self.target:
                continue

            sport, dport = struct.unpack('!HH', pkt[ihl:ihl + 4])
            seq, ack = struct.unpack('!II', pkt[ihl + 4:ihl + 12])
            flags = pkt[ihl + 13]

            with self._lock:
                rec = self._pending.get((dport, sport))
                if rec is None:
                    continue
                if (flags & 0x12) == 0x12:        # SYN + ACK
                    rec['state'] = 'open'
                    rec['ack'] = ack
                elif (flags & 0x04) == 0x04:      # RST / RST+ACK
                    rec['state'] = 'closed'
                else:
                    continue
                rec['event'].set()

    def scan_port(self, port):
        for _ in range(self.retries + 1):
            sport = random.randint(32768, 60999)
            seq = random.randint(0, 0xFFFFFFFF)
            ev = threading.Event()
            rec = {'event': ev, 'state': None, 'ack': 0}
            key = (port, sport)

            with self._lock:
                self._pending[key] = rec
            try:
                pkt = build_tcp_packet(self.src_ip, self.target, sport, port, seq, 0, 0x02)
                with self._send_lock:
                    self._send_sock.sendto(pkt, (self.target, 0))
                ev.wait(self.timeout)
            finally:
                with self._lock:
                    self._pending.pop(key, None)

            if rec['state'] == 'open':
                try:                                       # RST 关掉半开连接
                    rst = build_tcp_packet(self.src_ip, self.target, sport, port,
                                           rec['ack'], 0, 0x04)
                    with self._send_lock:
                        self._send_sock.sendto(rst, (self.target, 0))
                except OSError:
                    pass
                return ('open', '')
            if rec['state'] == 'closed':
                return ('closed', '')
        return ('filtered', '')

    def close(self):
        self._stop.set()
        self._sniffer.join(timeout=1.0)
        for s in (self._recv_sock, self._send_sock):
            try:
                s.close()
            except OSError:
                pass


class ScapySynScanner:
    """给 Windows / 无 Npcap raw 能力的环境用。需要 pip install scapy。"""

    def __init__(self, target, timeout=1.0, retries=1, src_ip=None, verbose=False):
        from scapy.all import IP, TCP, sr1, send   # noqa: F401
        self._IP, self._TCP, self._sr1, self._send = IP, TCP, sr1, send
        self.target = target
        self.timeout = timeout
        self.retries = retries
        self.verbose = verbose
        self.src_ip = src_ip or local_ip_for(target)

    def scan_port(self, port):
        for _ in range(self.retries + 1):
            sport = random.randint(32768, 60999)
            seq = random.randint(0, 0xFFFFFFFF)
            pkt = self._IP(src=self.src_ip, dst=self.target) / self._TCP(
                sport=sport, dport=port, flags='S', seq=seq)
            resp = self._sr1(pkt, timeout=self.timeout, verbose=0)
            if resp is None:
                continue
            if not resp.haslayer(self._TCP):
                continue
            fl = int(resp[self._TCP].flags)
            if (fl & 0x12) == 0x12:
                try:
                    self._send(self._IP(src=self.src_ip, dst=self.target) / self._TCP(
                        sport=sport, dport=port, flags='R',
                        seq=int(resp[self._TCP].ack)), verbose=0)
                except Exception:
                    pass
                return ('open', '')
            if fl & 0x04:
                return ('closed', '')
        return ('filtered', '')

    def close(self):
        pass

# ---------------------------------------------------------------- banner 抓取


def _probe_for(port, host):
    if port in HTTP_PORTS:
        return (b'HEAD / HTTP/1.0\r\nHost: ' + host.encode() +
                b'\r\nUser-Agent: Mozilla/5.0 (pscan)\r\nAccept: */*\r\n\r\n')
    if port == 6379:
        return b'PING\r\n'
    if port == 11211:
        return b'version\r\n'
    if port in (25, 587):
        return b'EHLO pscan.local\r\n'
    if port == 110:
        return b'USER pscan\r\n'
    if port == 143:
        return b'a1 CAPABILITY\r\n'
    return None


def _recv_banner(sock, timeout, limit=2048):
    sock.settimeout(timeout)
    data = b''
    try:
        while len(data) < limit:
            chunk = sock.recv(limit - len(data))
            if not chunk:
                break
            data += chunk
            if b'\n' in data or len(chunk) < 512:
                break
    except (socket.timeout, OSError, ssl.SSLError):
        pass
    text = data.decode('latin-1', 'replace').replace('\r\n', ' | ').replace('\n', ' | ')
    return text.strip(' |')[:400]


def grab_banner(sock, host, port, timeout):
    try:
        if port in TLS_PORTS:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            ctx.minimum_version = ssl.TLSVersion.TLSv1
            sock.settimeout(timeout)
            try:
                tls = ctx.wrap_socket(sock, server_hostname=host)
            except (ssl.SSLError, OSError):
                return ''
            try:
                cipher = tls.cipher()[0] if tls.cipher() else '?'
                info = '%s/%s' % (tls.version() or 'TLS', cipher)
                if port in (443, 8443, 9443, 6443):
                    try:
                        tls.sendall(b'HEAD / HTTP/1.0\r\nHost: ' + host.encode() +
                                    b'\r\nUser-Agent: pscan\r\n\r\n')
                    except OSError:
                        pass
                body = _recv_banner(tls, timeout)
                return (info + ' | ' + body) if body else info
            finally:
                try:
                    tls.close()
                except OSError:
                    pass

        probe = _probe_for(port, host)
        if probe:
            try:
                sock.sendall(probe)
            except OSError:
                pass
        return _recv_banner(sock, timeout)
    except Exception:
        return ''

# ---------------------------------------------------------------- connect 扫描器


class ConnectScanner:
    def __init__(self, target, timeout=1.0, retries=1, banner=False, banner_timeout=2.0,
                 verbose=False):
        self.target = target
        self.timeout = timeout
        self.retries = retries
        self.banner = banner
        self.banner_timeout = banner_timeout
        self.verbose = verbose

    def scan_port(self, port):
        for attempt in range(self.retries + 1):
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.settimeout(self.timeout)
            try:
                rc = s.connect_ex((self.target, port))
            except OSError as exc:
                rc = exc.errno if exc.errno is not None else -1

            if rc == 0:
                banner = ''
                if self.banner:
                    banner = grab_banner(s, self.target, port, self.banner_timeout)
                try:
                    s.close()
                except OSError:
                    pass
                return ('open', banner)

            try:
                s.close()
            except OSError:
                pass

            if rc in (errno.ECONNREFUSED, WSAECONNREFUSED):
                return ('closed', '')
            if attempt < self.retries:
                time.sleep(min(0.15 * (attempt + 1), 1.0))
        return ('filtered', '')


def grab_banner_connect(target, port, timeout):
    """SYN 扫描后对 open 端口补一次 banner。"""
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(timeout)
    try:
        if s.connect_ex((target, port)) != 0:
            return ''
        return grab_banner(s, target, port, timeout)
    finally:
        try:
            s.close()
        except OSError:
            pass

# ---------------------------------------------------------------- 驱动


def parse_ports(spec):
    ports, seen = [], set()
    for part in spec.split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            lo, hi = part.split('-', 1)
            lo, hi = int(lo), int(hi)
            if lo > hi:
                lo, hi = hi, lo
            seq = range(lo, hi + 1)
        else:
            seq = [int(part)]
        for p in seq:
            if 0 < p < 65536 and p not in seen:
                seen.add(p)
                ports.append(p)
    return ports


def main(argv=None):
    ap = argparse.ArgumentParser(
        description='多线程端口扫描器 (SYN / connect)，带重试与 banner 抓取')
    ap.add_argument('-t', '--target', required=True, help='目标 IP 或域名')
    ap.add_argument('-p', '--ports', default='1-1024',
                    help='端口表达式: 22,80,443 或 1-1024 或混合 1-100,3306,8080-8090')
    ap.add_argument('--mode', choices=['connect', 'syn'], default='connect')
    ap.add_argument('--syn-backend', choices=['raw', 'scapy'], default='raw')
    ap.add_argument('-T', '--threads', type=int, default=200)
    ap.add_argument('--timeout', type=float, default=1.0,
                    help='单次探测超时秒 (SYN: 等 SYN-ACK 的时长)')
    ap.add_argument('-r', '--retries', type=int, default=1,
                    help='超时重试次数 (不含首次)')
    ap.add_argument('--banner', action='store_true', help='抓取服务 banner')
    ap.add_argument('--banner-timeout', type=float, default=2.0)
    ap.add_argument('-o', '--json', dest='json_out', help='结果写入 JSONL 文件')
    ap.add_argument('-v', '--verbose', action='store_true', help='打印 closed/filtered')
    ap.add_argument('--src-ip', help='SYN 模式源 IP (默认按路由自动选)')
    args = ap.parse_args(argv)

    try:
        target_ip = socket.gethostbyname(args.target)
    except socket.gaierror as exc:
        print('[!] 域名解析失败: %s' % exc, file=sys.stderr)
        return 2

    ports = parse_ports(args.ports)
    if not ports:
        print('[!] 端口表达式为空', file=sys.stderr)
        return 2

    if args.mode == 'syn':
        if args.syn_backend == 'scapy':
            try:
                scanner = ScapySynScanner(target_ip, args.timeout, args.retries,
                                          args.src_ip, args.verbose)
            except ImportError:
                print('[!] 未安装 scapy: pip install scapy', file=sys.stderr)
                return 3
        else:
            if hasattr(os, 'geteuid') and os.geteuid() != 0:
                print('[!] SYN 模式需要 root / CAP_NET_RAW', file=sys.stderr)
                return 3
            try:
                scanner = SynScanner(target_ip, args.timeout, args.retries,
                                     args.src_ip, args.verbose)
            except PermissionError:
                print('[!] raw socket 权限不足，用 sudo 或 --syn-backend scapy',
                      file=sys.stderr)
                return 3
    else:
        scanner = ConnectScanner(target_ip, args.timeout, args.retries,
                                 args.banner, args.banner_timeout, args.verbose)

    print('[*] %s (%s) 端口 %d 个 | 模式 %s | 线程 %d | timeout %.2fs | retries %d'
          % (args.target, target_ip, len(ports), args.mode, args.threads,
             args.timeout, args.retries))

    out = open(args.json_out, 'w', encoding='utf-8') if args.json_out else None
    print_lock = threading.Lock()
    open_ports = []
    stats = {'open': 0, 'closed': 0, 'filtered': 0}
    t0 = time.time()

    def emit(port, state, banner):
        svc = SERVICES.get(port, '')
        line = '[+] %s:%-5d %-6s %-14s %s' % (target_ip, port, state, svc, banner)
        with print_lock:
            if state == 'open':
                print(line)
            elif args.verbose:
                print('[-] %s:%-5d %s' % (target_ip, port, state))
            if out:
                out.write(json.dumps({
                    'target': target_ip, 'port': port, 'state': state,
                    'service': svc, 'banner': banner,
                    'ts': round(time.time(), 3),
                }, ensure_ascii=False) + '\n')
                out.flush()

    try:
        with ThreadPoolExecutor(max_workers=max(1, args.threads)) as pool:
            futs = {pool.submit(scanner.scan_port, p): p for p in ports}
            try:
                for fut in as_completed(futs):
                    port = futs[fut]
                    try:
                        state, banner = fut.result()
                    except Exception as exc:
                        state, banner = 'filtered', ''
                        if args.verbose:
                            print('[!] %d 探测异常: %r' % (port, exc), file=sys.stderr)
                    stats[state] = stats.get(state, 0) + 1
                    if state == 'open':
                        open_ports.append((port, banner))
                    emit(port, state, banner)
            except KeyboardInterrupt:
                for f in futs:
                    f.cancel()
                raise
    except KeyboardInterrupt:
        print('\n[!] 中断，输出已扫描部分', file=sys.stderr)
    finally:
        if not isinstance(scanner, ConnectScanner):
            scanner.close()

    # SYN 模式下补 banner
    if args.mode == 'syn' and args.banner and open_ports:
        print('[*] 对 %d 个 open 端口补抓 banner...' % len(open_ports))
        with ThreadPoolExecutor(max_workers=min(32, len(open_ports))) as pool:
            futs = {pool.submit(grab_banner_connect, target_ip, p, args.banner_timeout): p
                    for p, _ in open_ports}
            for fut in as_completed(futs):
                port = futs[fut]
                try:
                    b = fut.result()
                except Exception:
                    b = ''
                if b:
                    print('    %s:%-5d %s' % (target_ip, port, b))

    elapsed = time.time() - t0
    print('[*] 完成: open=%d closed=%d filtered=%d 用时 %.2fs'
          % (stats.get('open', 0), stats.get('closed', 0),
             stats.get('filtered', 0), elapsed))
    if out:
        out.close()
    return 0


if __name__ == '__main__':
    sys.exit(main())
```

关键实现点：

**SYN 模式的两个后端。** `SynScanner` 自己拼 IP/TCP 头（`IP_HDRINCL` 发送 + 独立 raw socket 收包），校验和用 RFC1071，`_pending` 字典按 `(dport, sport)` 索引探针，嗅探线程收到 `SYN+ACK` 判 open、`RST` 判 closed，open 后补发 `RST`（seq 取对端 ack）关掉半开连接。`ScapySynScanner` 走 `sr1`，给 Windows/无 raw 权限的环境兜底。

**重试语义。** connect 模式对 `ECONNREFUSED`（含 Windows 的 10061）直接返回 closed，不做无意义重试；只有超时/不可达才按 `0.15s * n` 退避重试。SYN 模式每次重试换新源端口和新 ISN。

**banner 抓取。** 按端口选探针：HTTP 端口发 `HEAD`，6379 发 `PING`，110 发 `USER`，25/587 发 `EHLO`，143 发 `CAPABILITY`；TLS 端口先握手再取协议版本+套件，443 类再叠一个 HTTP HEAD。

**一个坑提醒。** `flags & 0x12 == 0x12` 在 Python 里会解析成 `flags & (0x12 == 0x12)`，比较运算符优先级高于位运算，所以代码里全部加了括号。这是 SYN 扫描器最常见的静默失效点。

本地验证命令：

```bash
# 造靶子
python3 -m http.server 8080 &
nc -lkv 127.0.0.1 2222 &

# connect 模式
python3 pscan.py -t 127.0.0.1 -p 1-10000 --mode connect --banner

# SYN 模式（需 root）
sudo python3 pscan.py -t 127.0.0.1 -p 1-10000 --mode syn --banner -v
