## 4. `pepatch.py`（可执行）

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""pepatch.py — PE32/PE32+ 定位辅助与定点 patch

  info      <file>
  scan      <file> "<AOB pattern>"           ?? 为通配
  rva2off   <file> <rva>
  off2rva   <file> <off>
  patch     <file> --rva X | --off X | --va X --base B
                   --bytes "B8 01 00 00 00 C3"
                   [--fix-checksum] [--dry-run] [--no-backup]
"""
import sys, os, struct, shutil, argparse

def die(m):
    print('[-] %s' % m, file=sys.stderr)
    sys.exit(1)

class PE(object):
    def __init__(self, path):
        self.path = path
        try:
            self.data = bytearray(open(path, 'rb').read())
        except IOError as e:
            die('open failed: %s' % e)
        d = self.data
        if len(d) < 0x40 or d[:2] != b'MZ':
            die('not a PE (no MZ)')
        e = struct.unpack_from('<I', d, 0x3C)[0]
        if d[e:e+4] != b'PE\0\0':
            die('not a PE (no signature)')
        coff = e + 4
        self.machine   = struct.unpack_from('<H', d, coff)[0]
        self.nsec      = struct.unpack_from('<H', d, coff + 2)[0]
        self.opt_size  = struct.unpack_from('<H', d, coff + 16)[0]
        self.opt       = coff + 20
        self.magic     = struct.unpack_from('<H', d, self.opt)[0]
        if self.magic == 0x20b:
            self.is64 = True
            self.image_base = struct.unpack_from('<Q', d, self.opt + 24)[0]
        elif self.magic == 0x10b:
            self.is64 = False
            self.image_base = struct.unpack_from('<I', d, self.opt + 28)[0]
        else:
            die('bad optional header magic 0x%x' % self.magic)
        self.ep_rva          = struct.unpack_from('<I', d, self.opt + 16)[0]
        self.size_of_image   = struct.unpack_from('<I', d, self.opt + 56)[0]
        self.size_of_headers = struct.unpack_from('<I', d, self.opt + 60)[0]
        self.checksum_off    = self.opt + 64
        self.checksum        = struct.unpack_from('<I', d, self.checksum_off)[0]
        self.sections = []
        sh = self.opt + self.opt_size
        for i in range(self.nsec):
            o = sh + i * 40
            name = d[o:o+8].rstrip(b'\0').decode('latin-1')
            vsize, vaddr, rsize, raddr = struct.unpack_from('<IIII', d, o + 8)
            chars = struct.unpack_from('<I', d, o + 36)[0]
            self.sections.append(dict(name=name, vsize=vsize, vaddr=vaddr,
                                      rsize=rsize, raddr=raddr, chars=chars))

    def rva2off(self, rva):
        for s in self.sections:
            span = max(s['vsize'], s['rsize'])
            if s['vaddr'] <= rva < s['vaddr'] + span:
                delta = rva - s['vaddr']
                if delta >= s['rsize']:
                    die('rva 0x%x 落在 %s 的未初始化区 (.bss)' % (rva, s['name']))
                return s['raddr'] + delta
        if rva < self.size_of_headers:
            return rva
        die('rva 0x%x 不属于任何节' % rva)

    def off2rva(self, off):
        for s in self.sections:
            if s['raddr'] <= off < s['raddr'] + s['rsize']:
                return s['vaddr'] + (off - s['raddr'])
        if off < self.size_of_headers:
            return off
        die('off 0x%x 不属于任何节' % off)

    def calc_checksum(self):
        d = bytearray(self.data)
        struct.pack_into('<I', d, self.checksum_off, 0)
        if len(d) & 1:
            d += b'\0'
        s = 0
        for i in range(0, len(d), 2):
            s += d[i] | (d[i + 1] << 8)
            s = (s & 0xFFFF) + (s >> 16)
        s = (s & 0xFFFF) + (s >> 16)
        return (s + len(self.data)) & 0xFFFFFFFF


def parse_aob(pat):
    out = []
    for tok in pat.replace(',', ' ').split():
        out.append(None if tok in ('??', '?', '**') else int(tok, 16))
    return out


def aob_scan(data, pat):
    first = next((i for i, v in enumerate(pat) if v is not None), None)
    if first is None:
        die('pattern 全通配')
    res, start, needle = [], 0, bytes([pat[first]])
    n = len(pat)
    while True:
        j = data.find(needle, start)
        if j < 0:
            break
        s = j - first
        if s >= 0 and s + n <= len(data):
            if all(pat[k] is None or data[s + k] == pat[k] for k in range(n)):
                res.append(s)
        start = j + 1
    return res


def main():
    ap = argparse.ArgumentParser(add_help=True)
    sub = ap.add_subparsers(dest='cmd')

    sub.add_parser('info').add_argument('file')
    p = sub.add_parser('scan'); p.add_argument('file'); p.add_argument('pattern')
    p = sub.add_parser('rva2off'); p.add_argument('file'); p.add_argument('rva')
    p = sub.add_parser('off2rva'); p.add_argument('file'); p.add_argument('off')

    p = sub.add_parser('patch')
    p.add_argument('file')
    p.add_argument('--rva'); p.add_argument('--off'); p.add_argument('--va'); p.add_argument('--base')
    p.add_argument('--bytes', required=True)
    p.add_argument('--fix-checksum', action='store_true')
    p.add_argument('--dry-run', action='store_true')
    p.add_argument('--no-backup', action='store_true')

    a = ap.parse_args()
    if not a.cmd:
        ap.print_help(); return
    pe = PE(a.file)

    if a.cmd == 'info':
        print('file          : %s' % a.file)
        print('machine       : 0x%04x (%s)' % (pe.machine, {0x8664:'x86-64',0x14c:'i386',0xaa64:'arm64'}.get(pe.machine,'?')))
        print('image_base    : 0x%x' % pe.image_base)
        print('entry_rva     : 0x%x  -> file_off 0x%x' % (pe.ep_rva, pe.rva2off(pe.ep_rva)))
        print('size_of_image : 0x%x' % pe.size_of_image)
        print('checksum      : 0x%08x' % pe.checksum)
        print('%-10s %-10s %-10s %-10s %-10s' % ('name','vaddr','vsize','raddr','rsize'))
        for s in pe.sections:
            print('%-10s 0x%-8x 0x%-8x 0x%-8x 0x%-8x' % (s['name'], s['vaddr'], s['vsize'], s['raddr'], s['rsize']))
        return

    if a.cmd == 'scan':
        pat = parse_aob(a.pattern)
        hits = aob_scan(pe.data, pat)
        print('[i] %d hit(s) for "%s"' % (len(hits), a.pattern))
        for h in hits:
            try:
                print('    file_off=0x%-8x rva=0x%x' % (h, pe.off2rva(h)))
            except SystemExit:
                print('    file_off=0x%-8x rva=<header>' % h)
        return

    if a.cmd == 'rva2off':
        rva = int(a.rva, 0); off = pe.rva2off(rva)
        print('rva 0x%x -> file_off 0x%x' % (rva, off)); return

    if a.cmd == 'off2rva':
        off = int(a.off, 0); rva = pe.off2rva(off)
        print('file_off 0x%x -> rva 0x%x' % (off, rva)); return

    if a.cmd == 'patch':
        blob = bytes(int(x, 16) for x in a.bytes.replace(',', ' ').split())
        if a.va:
            if not a.base: die('--va 需要 --base')
            rva = int(a.va, 0) - int(a.base, 0)
            if rva < 0 or rva >= pe.size_of_image:
                die('VA 不在模块范围内 (rva=0x%x)' % rva)
            off = pe.rva2off(rva)
        elif a.rva:
            rva = int(a.rva, 0); off = pe.rva2off(rva)
        elif a.off:
            off = int(a.off, 0); rva = pe.off2rva(off)
        else:
            die('需要 --rva / --off / --va')

        if off + len(blob) > len(pe.data):
            die('patch 越界')
        old = bytes(pe.data[off:off + len(blob)])
        print('[i] %s  rva=0x%x  file_off=0x%x  len=%d' % (a.file, rva, off, len(blob)))
        print('[i] before: %s' % old.hex(' ').upper())
        print('[i] after : %s' % blob.hex(' ').upper())
        if old == blob:
            print('[=] 已是目标字节，跳过'); return
        if a.dry_run:
            print('[=] dry-run，未写入'); return

        if not a.no_backup:
            bak = a.file + '.bak'
            if not os.path.exists(bak):
                shutil.copy2(a.file, bak)
                print('[+] 备份 -> %s' % bak)
            else:
                print('[=] 备份已存在: %s' % bak)

        pe.data[off:off + len(blob)] = blob
        if a.fix_checksum and pe.checksum:
            nc = pe.calc_checksum()
            struct.pack_into('<I', pe.data, pe.checksum_off, nc)
            print('[+] checksum 0x%08x -> 0x%08x' % (pe.checksum, nc))
        open(a.file, 'wb').write(pe.data)
        print('[+] 写入完成 (size 不变: %d)' % len(pe.data))
        return

if __name__ == '__main__':
    main()
```

