## 5. Frida 侧：定位 + 内存 patch（有文件完整性校验时用）

不落盘、只改进程内存，绕过 CRC/签名自检。

`patch_mem.js`：

```js
// frida -f SAMPLE.exe -l patch_mem.js --runtime=v8
// 用法: frida ... -- --rva 0x1234 --bytes "B8 01 00 00 00 C3"
const MODNAME = 'SAMPLE.exe';

function arg(name, dflt) {
  const i = Process.argv.indexOf('--' + name);
  return i >= 0 ? Process.argv[i + 1] : dflt;
}
const RVA   = parseInt(arg('rva', '0x0'), 16);
const BYTES = arg('bytes', 'B8 01 00 00 00 C3').split(/\s+/).map(x => parseInt(x, 16));

const mod = Process.findModuleByName(MODNAME) || Process.enumerateModules()[0];
const addr = mod.base.add(RVA);

console.log(`[*] ${mod.name} base=${mod.base} rva=0x${RVA.toString(16)} target=${addr}`);
console.log(`[*] before: ${addr.readByteArray(BYTES.length) ? Array.from(new Uint8Array(addr.readByteArray(BYTES.length))).map(b => b.toString(16).padStart(2,'0')).join(' ') : '-'}`);

Memory.protect(addr, 0x1000, 'rwx');
addr.writeByteArray(BYTES);

console.log(`[*] after : ${Array.from(new Uint8Array(addr.readByteArray(BYTES.length))).map(b => b.toString(16).padStart(2,'0')).join(' ')}`);

// 返回值探针：确认 patch 生效
Interceptor.attach(addr, {
  onEnter() {},
  onLeave(r) { console.log(`[probe] CHECK_FN 返回 ${r} (int32=${r.toInt32()})`); }
});
```

`MemoryAccessMonitor` 版本（自动定位读取 KEY 的指令，对应 §1.2）：

```js
// frida -f SAMPLE.exe -l watch_buf.js --runtime=v8
const MODNAME = 'SAMPLE.exe';
let mod = null;
const getMod = () => mod || (mod = Process.findModuleByName(MODNAME) || Process.enumerateModules()[0]);
const rel = p => { const m = Process.findModuleByAddress(p); return m ? `${m.name}+0x${p.sub(m.base).toString(16)}` : p.toString(); };

['GetDlgItemTextW','GetWindowTextW','GetWindowTextA'].forEach(n => {
  const a = Module.findExportByName(null, n);
  if (!a) return;
  Interceptor.attach(a, {
    onLeave(r) {
      const buf = this.context.rcx || this.context.ecx;   // x64 第一个参数
      if (!buf || buf.isNull()) return;
      const size = 0x100;
      try {
        MemoryAccessMonitor.enable({ base: buf, size: size }, {
          onAccess(d) {
            console.log(`[access] op=${d.operation} from=${rel(d.from)} addr=${d.address}`);
            MemoryAccessMonitor.disable();
            // 打印该指令前后 16 字节，供 IDA 里定位函数入口
            console.log(hexdump(d.from.sub(16), { length: 48, ansi: false }));
          }
        });
        console.log(`[*] watching buffer ${buf} (${n})`);
      } catch (e) { console.log('[-] monitor: ' + e); }
    }
  });
});
